"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5240],{8308(a){a.exports=JSON.parse('{"title":"\uc5b4\ub5bb\uac8c \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4dc\ub294\uac00","date":"2024-12-06","coverUrl":"/kudzu-based-bench/assets/notion/f838941644ecba0c.png","html":"<h2 data-notion-block-id=\\"150e548d-8a8e-8052-b12e-c7fcfe066813\\" id=\\"150e548d-8a8e-8052-b12e-c7fcfe066813\\">\uc5b4\ub5bb\uac8c \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4dc\ub294\uac00</h2><a href=\\"https://www.developerway.com/posts/hard-react-questions-and-modal-dialog\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/hard-react-questions-and-modal-dialog</a><p data-notion-block-id=\\"150e548d-8a8e-806d-a7f4-f129473b25ed\\"><b>\uc2ec\uc724\uc12d</b>: \ub9ac\uc561\ud2b8\uc5d0\uc11c \uac00\uc7a5 \uc5b4\ub824\uc6b4 \ubd80\ubd84\uc778 \\"\ucef4\ud3ec\ub10c\ud2b8\ub97c <b>\uc798</b> \ub9cc\ub4dc\ub294 \ubc95\\"\uc744 \uacfc\uc815\uc744 \ub2e8\uacc4\ub97c \ubc1f\uc544\uac00\uba70 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \uc798 \ub9cc\ub4dc\ub294 \ubc95\uc758 \uc815\uc758\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uc774 \uacfc\uc815\uc744 \ubc18\ubcf5\ud558\ub2e4\ubcf4\uba74 \ub354 \ub098\uc740 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4dc\ub294\ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uae00\uc758 5\ub2e8\uacc4\uc5d0\uc11c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc18c\uac1c\ud558\ub4ef\uc774, \uc5ec\ub7ec UI \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc740 \uc5ec\ub7ec \uc5e3\uc9c0 \ucf00\uc774\uc2a4\uc640 \uc5ec\ub7ec \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\ucdb0 \uc0dd\uae34 \uacb0\uacfc\ubb3c\ub4e4\uc785\ub2c8\ub2e4. \ubb3c\ub860 UI \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub294 \uad11\ub300\ud558\uae30\uc5d0 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ubaa8\ub4e0 \uae30\ub2a5\uc744 \uac00\uc838\uc62c \uc218\ub294 \uc5c6\uaca0\uc9c0\ub9cc, \ub0b4\uac00 \ub9c8\uc8fc\uce5c \uc694\uad6c\uc0ac\ud56d\uc815\ub3c4\ub294 \ubd84\uc11d\ud574\uc11c \uc801\uc6a9\ud558\uac70\ub098 \ub9ce\uc740 \uc0ac\ub78c\uc5d0\uac8c \uac80\uc99d\ub41c \uc778\ud130\ud398\uc774\uc2a4\ub97c \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\uc744 \uac83\uc785\ub2c8\ub2e4. \ucd94\uc0c1\ud654\uc5d0 \ub300\ud55c \uae00\uc740 \uc5ec\ub7ec\uac00\uc9c0 \uae00(\uac00\uc7a5 \ucd5c\uadfc \ub274\uc2a4\ub808\ud130\uc5d0\uc11c \uc18c\uac1c\ub41c <a href=\\"https://ones-to-watch.ethansup.net/news/post/fa08117a-8884-4c6c-a884-e39b5c1d607d#80e87956-671b-44f6-a930-7cda0f6394c3\\">\ucd94\uc0c1\ud654\uc640 \uac04\uc811\uc801\uc778 \ub808\uc774\uc5b4\uc758 \ucc28\uc774</a>\ub97c \ucc38\uace0\ud558\uc138\uc694)\uc774 \uc788\uc9c0\ub9cc, \uc790\uc2e0\ub9cc\uc758 \uc694\uad6c\uc0ac\ud56d\uc744 \ubd84\uc11d\ud558\ub294 \ubc29\ubc95\uc744 \ub9cc\ub4e4\uc5b4\ubcf4\ub294\uac8c \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4. \uc81c\uac00 \uc0dd\uac01\ud558\ub294 \uad00\uc810\uc740 <a href=\\"https://youtu.be/TSeLYDN1Mo0?si=SfeXi6phaaEMlqpK\\">\uc81c\uac00 \ubc1c\ud45c\ud55c \ub3d9\uc601\uc0c1</a>\uc744 \ucc38\uace0\ud558\uc138\uc694 \ud83d\ude05</p><h2 data-notion-block-id=\\"150e548d-8a8e-80c7-9a97-e43614d6ff9d\\" id=\\"150e548d-8a8e-80c7-9a97-e43614d6ff9d\\">Island Architecture\ub85c \ub9ac\ucf54\ub4dc \ub300\uc2e0 \ud1b5\ud569\ud558\uae30</h2><a href=\\"https://swizec.com/blog/the-anatomy-of-a-react-island/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://swizec.com/blog/the-anatomy-of-a-react-island/</a><p data-notion-block-id=\\"150e548d-8a8e-80c8-b9ad-c1afed1b33ca\\"><b>\uc2ec\uc724\uc12d</b>: \uae30\uc874 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \uae30\ubc18 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubc14\uafb8\ub294 \uac83\uc740 \uc624\ub79c \uc2dc\uac04\uc774 \uac78\ub9bd\ub2c8\ub2e4. \uc774\uc5d0 \ud574\uacb0\ucc45\uc73c\ub85c \uae30\uc874 \uc2dc\uc2a4\ud15c\uacfc \ud1b5\ud569\ud560 \uc218 \uc788\ub294 Island Archtecture\ub97c React\ub97c \uae30\ubc18\uc73c\ub85c \uad6c\ucd95\ud558\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 React + Vite\ub85c \uad6c\ud604\ud558\uc600\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/132e548d-8a8e-80db-a33c-f4337d20c800#134e548d-8a8e-800d-affc-eb8869c2f8ad\\">Webpack + Preact\ub85c\ub3c4 \uad6c\ud604\ud560 \uc218 \uc788</a>\uc73c\uba70, \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \uad6c\ud604\ud558\uae30 \ub54c\ubb38\uc5d0 \uc0ac\uc6a9\ud558\ub824\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ud2b9\uc131\uc744 \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-8078-b060-e7c2fd648a72\\" id=\\"150e548d-8a8e-8078-b060-e7c2fd648a72\\">AutoScrollList \ucef4\ud3ec\ub10c\ud2b8 \ub9cc\ub4e4\uae30</h2><a href=\\"https://www.nikhilsnayak.dev/blogs/the-auto-scroll-list-component\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nikhilsnayak.dev/blogs/the-auto-scroll-list-component</a><p data-notion-block-id=\\"150e548d-8a8e-8016-b4bf-e64772729c1e\\">AI \ucc57\ubd07\uc6a9 AutoScrollList \ucef4\ud3ec\ub10c\ud2b8\ub97c \uad6c\ud604\ud558\uba74\uc11c \ub9c8\uc8fc\uce5c \uc5ec\ub7ec \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4. ref\ub97c \uc120\uc5b8\ud560 \ub54c <code>useCallback</code>\uc744 \uc0ac\uc6a9\ud558\uba74 \ub9ac\uc561\ud2b8 \ucef4\ud30c\uc77c\ub7ec\uc5d0\uc11c \uc624\ub958\uac00 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc774 \uc778\uc0c1\uc801\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80fa-8daf-d3068249ccd6\\" id=\\"150e548d-8a8e-80fa-8daf-d3068249ccd6\\">\ube0c\ub77c\uc6b0\uc800 fallback\uc744 \ub2e4\ub8e8\ub294 \ubc29\uc2dd</h2><a href=\\"https://www.joshwcomeau.com/css/browser-support/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/css/browser-support/</a><p data-notion-block-id=\\"150e548d-8a8e-8019-9fb5-dbad1b3cafbf\\">\uc0c8\ub85c\uc6b4 JS, CSS \ubb38\ubc95\uc744 \uc0ac\uc6a9\ud560 \ub54c, \uc11c\ube44\uc2a4\uc5d0\uc11c \uac04\ub2e8\ud558\uac8c \uace0\ub824\ud574\ubcfc\ub9cc\ud55c \uac83\uc744 \uc815\ub9ac\ud55c \uae00\uc785\ub2c8\ub2e4. \uc11c\ube44\uc2a4\uc5d0 \ub530\ub77c \ubaa8\ub4e0 \ud658\uacbd\uc5d0\uc11c \ucd5c\ub300\ud55c \ub611\uac19\uc740 \uacbd\ud5d8\uc744 \uc81c\uacf5\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uace0, \uae00\uc5d0 \ub530\ub77c \uc18c\uc218\uc758 \ud658\uacbd\uc5d0\uc11c\ub294 \ub2e4\ub978 \uacbd\ud5d8\uc744 \uc81c\uacf5\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc73c\ubbc0\ub85c, \uc804\ub7b5\uc744 \uc798 \uc138\uc6cc\uc57c\uaca0\ub124\uc694. \uacbd\uc6b0\uc5d0 \ub530\ub77c UA\uc5d0 \ub530\ub978 polyfill\uc744 \uc81c\uacf5\ud558\uac70\ub098, \ud2b8\ub79c\uc2a4\ud30c\uc77c\uc744 \ud1b5\ud574 \uc61b\ub0a0 \ubb38\ubc95\uc73c\ub85c \uce58\ud658\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80ee-93e2-fc3ef01bf10f\\" id=\\"150e548d-8a8e-80ee-93e2-fc3ef01bf10f\\">Tanstack Start..</h2><a href=\\"https://tanstack.com/blog/why-tanstack-start-is-ditching-adapters\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/why-tanstack-start-is-ditching-adapters</a><a href=\\"https://frontendmasters.com/blog/introducing-tanstack-router/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/introducing-tanstack-router/</a><p data-notion-block-id=\\"150e548d-8a8e-80ef-a678-cf7c5041e667\\">\uccab \uae00\uc740 Tanstack Start\uac00 <a href=\\"https://vinxi.vercel.app/\\">Vinxi</a>\ub97c \uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc838 \ub2e4\uc591\ud55c \ud658\uacbd\uc744 \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uae00\uc774\uace0, \ub450\ubc88\uc9f8 \uae00\uc740 Tanstack Router\ub97c \uc18c\uac1c\ud558\ub294 \uc2dc\ub9ac\uc988 \uae00\ub85c \ud504\ub808\uc784\uc6cc\ud06c\ub9cc\uc758 \ud2b9\uc9d5\uc744 \uc798 \uc9da\uc5b4\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"155e548d-8a8e-8004-a27c-c43910073021\\" id=\\"155e548d-8a8e-8004-a27c-c43910073021\\">Spring animation\uacfc \uc9c1\uad00\uc801 \uc811\uadfc \ubc29\uc2dd</h2><a href=\\"https://www.kvin.me/posts/effortless-ui-spring-animations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.kvin.me/posts/effortless-ui-spring-animations</a><p data-notion-block-id=\\"152e548d-8a8e-80df-813f-cf7f1e719772\\">\ub9e4\ub825\uc801\uc778 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \uc0ac\uc6a9\ub418\ub294 Spring \uc560\ub2c8\uba54\uc774\uc158\uc744 \uc811\uadfc\ud560 \ub54c \ubb3c\ub9ac\ud559\uc801\uc778 \uad00\uc810\uc778(\uc9c8\ub7c9/\uac15\uc131/\uac10\uc1e0) \ub300\uc2e0 \ub2e4\ub978 \uc811\uadfc \ubc29\uc2dd\uc73c\ub85c \uc560\ub2c8\uba54\uc774\uc158\uc744 \uc124\uc815\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"152e548d-8a8e-80b7-9a45-c16aab23a6a7\\" id=\\"152e548d-8a8e-80b7-9a45-c16aab23a6a7\\">\ud14c\uc2a4\ud2b8 \uc791\uc131\ud560 \ub54c \uac70\uc9d3 \uc591\uc131 \ubc29\uc9c0\ud558\uae30</h2><a href=\\"https://blog.appsignal.com/2024/11/20/avoiding-false-positives-in-nodejs-tests.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.appsignal.com/2024/11/20/avoiding-false-positives-in-nodejs-tests.html</a><p data-notion-block-id=\\"155e548d-8a8e-80be-9881-f2450dae7314\\">\ub300\ubd80\ubd84 \uc790\uc8fc \uc2e4\uc218\ud560\ub9cc\ud55c \ud14c\uc2a4\ud2b8 \ubc29\uc2dd \uc624\uc6a9\uc774\ub098 \ub9e4\uce6d \uba54\uc18c\ub4dc\ub97c \uc798\ubabb \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"152e548d-8a8e-80c6-97aa-c05c29dca568\\" id=\\"152e548d-8a8e-80c6-97aa-c05c29dca568\\">\ube0c\ub77c\uc6b0\uc800\uc640 \ub85c\ub529 \ub9e4\ucee4\ub2c8\uc998</h2><a href=\\"https://www.youtube.com/watch?v=p0lFyPuH8Zs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=p0lFyPuH8Zs</a><p data-notion-block-id=\\"152e548d-8a8e-805e-8106-df69274ebe95\\">\ube0c\ub77c\uc6b0\uc800\ub9c8\ub2e4 \ub85c\ub529 \ub9e4\ucee4\ub2c8\uc998\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0\uc640 \uc6b0\uc120\uc21c\uc704\uc5d0\uc11c \uc801\uc6a9\ub418\ub294 \uac1c\ub150\uc778 tight mode\ub97c \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c \uc601\uc0c1\uc785\ub2c8\ub2e4. <code>fetchPriority</code>\uc640 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ee307831cb464aafb912fff97004d37e#9104b914-c2e2-4996-84f6-a8cb82cb8a42\\">Speculation Rules API</a>, <code>rel=\\"preload\\"</code>\uc640 \uc5f0\uacb0\uc9d3\ub294 \uc911\uc694\ud55c \uc790\ub8cc\uc774\ubbc0\ub85c, API\ub97c \uc0ac\uc6a9\ud558\uc2e0\ub2e4\uba74 \ubcf4\uc2dc\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80ed-99aa-cdcbbe66934d\\" id=\\"150e548d-8a8e-80ed-99aa-cdcbbe66934d\\">RN\uc744 \uc4f0\uba74\uc11c \ubc30\uc6b4 \uad50\ud6c8</h2><a href=\\"https://fernandorojo.co/mistakes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fernandorojo.co/mistakes</a><p data-notion-block-id=\\"150e548d-8a8e-8057-a506-fc8acc7c4ff2\\">RN\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c \ubc30\uc6b4 \uad50\ud6c8\uc744 \uac04\ub2e8\ud558\uac8c \uc4f4 \uae00\uc785\ub2c8\ub2e4. \uc77c\uad00\uc131\uc788\ub294 UI\ubcf4\ub2e4 Android/iOS\uc5d0 \ud2b9\ud654\ub41c UI\uac00 \ub354 \uc778\uae30 \uc788\ub2e4\ub294 \uc810\uc740 \ud765\ubbf8\ub86d\ub124\uc694.</p><h2 data-notion-block-id=\\"150e548d-8a8e-80b1-83dd-ea431361561d\\" id=\\"150e548d-8a8e-80b1-83dd-ea431361561d\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c</h2><a href=\\"https://vite.dev/blog/announcing-vite6.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vite.dev/blog/announcing-vite6.html</a><a href=\\"https://remix.run/blog/react-router-v7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/react-router-v7</a><p data-notion-block-id=\\"150e548d-8a8e-8087-8b23-e128e72a2413\\">Vite 6\uc640 Vite \uae30\ubc18\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 React Router(Remix) 7\uc774 \ub4f1\uc7a5\ud588\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"151e548d-8a8e-802e-bdaf-c39cf3a43767\\"></p>"}')}}]);